// AdminVideoStorageStats is the resolver for the adminVideoStorageStats field.
func (r *queryResolver) AdminVideoStorageStats(ctx context.Context) (*model.VideoStorageStats, error) {
	if r.VideoService == nil {
		return nil, fmt.Errorf("video is not configured")
	}
	st, err := r.VideoService.Stats(ctx)
	if err != nil {
		return nil, err
	}
	daily := make([]*model.VideoDailyStat, 0, len(st.Daily))
	for _, d := range st.Daily {
		daily = append(daily, toGraphVideoDailyStat(d))
	}
	today := toGraphVideoDailyStat(st.Today)
	today.Day = toGraphVideoDailyStat(repository.VideoDailyStats{Day: st.StatsUntilDay}).Day
	month := toGraphVideoDailyStat(st.ThisMonth)
	month.Day = today.Day[:min(len(today.Day), 7)]
	return &model.VideoStorageStats{
		Settings:     toGraphVideoSettings(st.Policy, st.BackstopDays),
		Stored:       toGraphVideoUsage(st.Stored),
		PurgeFailing: float64(st.PurgeFailing),
		Today:        today,
		ThisMonth:    month,
		Daily:        daily,
	}, nil
}

